const fs=require('node:fs'),{engine,epoch}=require('./hypertower/tests/gr-helper.cjs');const {H,G}=engine(),D=G.Era24,s=epoch(H,G,24),rows=[];for(let q=0;q<300;q++){const word=q.toString(2).padStart(9,'0').split('').map(c=>c==='0'?1:2),r=D.register(s,word);rows.push({index:q,word,id:r.id,length:r.word.length,depth:r.depth,depthExact:r.depthExact});}const net={objects:['A','B','C','D'],arrows:[['ab','A','B'],['bc','B','C'],['cd','C','D'],['ac','A','C'],['bd','B','D'],['ad','A','D']].map(([id,a,b])=>({id,a,b,phase:0})),glues:[]};const summary={registered:rows.length,uniqueSources:new Set(rows.map(x=>x.id)).size,allLength9:rows.every(x=>x.length===9),allExactDepth1:rows.every(x=>x.depth===1&&x.depthExact),alreadyObservedStars:Object.values(s.p3.ep[24].objects).filter((o,i)=>s.p3.sky.obs[rows[i].id]?.star).length,threeHoleNet:net,threeHoleReport:D.groupoid(net),rows};fs.writeFileSync('walkthrough-work-20261101/p3-300-loop-family.json',JSON.stringify(summary,null,2));console.log(JSON.stringify({...summary,rows:rows.slice(0,6)},null,2));
